protected void prePromptModifyContract()
{
    AVAHandoverDocContract contract;

    super();

    if (!this.parmArgs() || !this.parmArgs().record())
    {
        return;
    }

    contract = this.parmReportContract().parmRdpContract();

    switch (this.parmArgs().record().TableId)
    {
        case tableNum(AVAHandoverDocTable):
            SysQuery::findOrCreateRange(this.getFirstQuery().dataSourceTable(tableNum(AVAHandoverDocTable)), fieldNum(AVAHandoverDocTable, RecId)).value(queryValue(this.parmArgs().record().(fieldNum(AVAHandoverDocTable, RecId))));
            break;
    }
}

public boolean showQuerySelectButton(str parameterName)
{
    boolean ret;

    ret = super(parameterName);

    if (!this.parmArgs() 
     || !this.parmArgs().record())
    {
        ret = true;
        this.parmLoadFromSysLastValue(true);
    }
    else
    {
        ret = false;
        this.parmLoadFromSysLastValue(false);
    }

    return ret;
}

public static void main(Args _args)
{

    AVAHandoverDocController controller = new AVAHandoverDocController();

    controller.parmReportName(ssrsReportStr(AVAHandoverDocReport, Report));
    controller.parmArgs(_args);
    controller.parmLoadFromSysLastValue(false);
    controller.startOperation();
}
